CREATE TABLE IF NOT EXISTS crm_customers (id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', company TEXT, email TEXT, phone TEXT, address TEXT, ship_address TEXT, notes TEXT, user_id TEXT, source TEXT NOT NULL DEFAULT 'manual', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT);
CREATE INDEX IF NOT EXISTS crm_customers_email ON crm_customers(lower(email));
CREATE INDEX IF NOT EXISTS crm_customers_user ON crm_customers(user_id);
CREATE TABLE IF NOT EXISTS invoices (id TEXT PRIMARY KEY, number INTEGER NOT NULL UNIQUE, customer_id TEXT NOT NULL, order_id TEXT, status TEXT NOT NULL DEFAULT 'draft', issue_date TEXT NOT NULL, due_date TEXT, discount_type TEXT NOT NULL DEFAULT 'amount', discount_value REAL NOT NULL DEFAULT 0, tax_rate REAL NOT NULL DEFAULT 0, subtotal REAL NOT NULL DEFAULT 0, discount REAL NOT NULL DEFAULT 0, tax REAL NOT NULL DEFAULT 0, total REAL NOT NULL DEFAULT 0, paid REAL NOT NULL DEFAULT 0, notes TEXT, bill_to TEXT, sent_at TEXT, voided_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT);
CREATE INDEX IF NOT EXISTS invoices_customer ON invoices(customer_id);
CREATE INDEX IF NOT EXISTS invoices_order ON invoices(order_id);
CREATE TABLE IF NOT EXISTS invoice_lines (id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL, pos INTEGER NOT NULL DEFAULT 0, kind TEXT NOT NULL DEFAULT 'sqft', description TEXT NOT NULL DEFAULT '', design_slug TEXT, design_title TEXT, qty REAL NOT NULL DEFAULT 0, rate REAL NOT NULL DEFAULT 0, amount REAL NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS invoice_lines_inv ON invoice_lines(invoice_id);
CREATE TABLE IF NOT EXISTS invoice_payments (id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL, paid_on TEXT NOT NULL, amount REAL NOT NULL, method TEXT NOT NULL DEFAULT 'other', note TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS invoice_payments_inv ON invoice_payments(invoice_id);
